responses.text:
{
  "microtasks": [
    {
      "id": 1,
      "description": "Search academic databases for at least three sources published between 2024 and 2026 that document the current severity or relevance of the research problem.",
      "prerequisites": []
    },
    {
      "id": 2,
      "description": "Read the selected 2024-2026 sources and extract key statistics, findings, or quotes that demonstrate the severity of the problem.",
      "prerequisites": [1]
    },
    {
      "id": 3,
      "description": "Draft the integration of the new 2024-2026 sources into the section of the Introduction that establishes the problem's severity.",
      "prerequisites": [2]
    },
    {
      "id": 4,
      "description": "Draft a single, explicit sentence that clearly states the research gap (e.g., 'However, what remains unexplored is...').",
      "prerequisites": []
    },
    {
      "id": 5,
      "description": "Insert the drafted research gap statement into the Introduction chapter, ensuring it logically follows the literature review.",
      "prerequisites": [4]
    },
    {
      "id": 6,
      "description": "Analyze the existing text between the background context and the problem statement to identify the exact point where the transition feels abrupt.",
      "prerequisites": []
    },
    {
      "id": 7,
      "description": "Draft bridging sentences or a transitional paragraph that connects the broad background context to the specific problem statement.",
      "prerequisites": [6]
    },
    {
      "id": 8,
      "description": "Integrate the drafted transitional sentences into the manuscript, revising surrounding sentences for smooth flow.",
      "prerequisites": [7]
    },
    {
      "id": 9,
      "description": "Add the full citations for the three new 2024-2026 sources to the thesis reference list.",
      "prerequisites": [3]
    },
    {
      "id": 10,
      "description": "Read through the entire revised Introduction chapter to ensure cohesive flow between the background, transition, problem statement, and research gap.",
      "prerequisites": [3, 5, 8, 9]
    }
  ]
}
